-- PT102-S4-Q12. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT102-S4-Q12$batch12$ AND q.stimulus=$batch12$The school principal insisted that student failures are caused by bad teaching. In a relatively short time failing grades disappeared from the school. The principal happily recognized this as evidence that the teaching had improved at the school.$batch12$ AND q.prompt=$batch12$The flawed pattern of reasoning in the above is most similar to that in which one of the following?$batch12$ AND q.correct_choice=$batch12$D$batch12$) THEN RAISE EXCEPTION 'Question changed: PT102-S4-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT102-S4-Q12$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S4-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT102-S4-Q12$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The teaching has improved.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$The principal believes bad teaching causes failures. Failures disappeared.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Nothing was observed about the teaching. The principal assumes the theory is right, sees the effect go away, and concludes the cause went away. Failures could have stopped for many other reasons.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Find someone who holds a theory about a cause, sees the effect stop, and concludes the cause stopped.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT102-S4-Q12$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Here the cause (overeating) is observed to stop and the effect is predicted. The original observes the effect and infers the cause.$batch12$), ($batch12$B$batch12$, $batch12$The manager actually changed the jobs. In the original, nobody did anything to the teaching.$batch12$), ($batch12$C$batch12$, $batch12$The nutritionist hands out charts and concludes the complaints stopped. No cause is inferred from a vanished effect.$batch12$), ($batch12$D$batch12$, $batch12$The manager's theory: complaints come from too little work. Complaints stopped, so the manager concludes the workers are busy. Same move.$batch12$), ($batch12$E$batch12$, $batch12$This relies on a report that the cause stopped and then concludes the effect stopped. That runs the other way.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT102-S4-Q12$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
